using System.Collections.Generic;
using UnityEngine;

namespace HotelTogether
{
    /// <summary>
    /// Central sound player. Clips live in Resources/HotelTogetherAudio (generated by
    /// Tools/Audio/generate_hotel_audio.py - drop in your own WAV/OGG with the same name to replace one).
    /// Every call is null-safe: a missing clip is simply silent.
    /// </summary>
    public static class HotelAudio
    {
        public const string Folder = "HotelTogetherAudio/";
        public static float MusicVolume = 1;
        public static float SfxVolume = 1;
        const string MusicPref = "HotelTogether.Settings.Music";

        static readonly Dictionary<string, AudioClip> clips = new();
        static readonly Dictionary<string, float> lastPlayed = new();
        static AudioSource ui;
        static AudioSource[] pool;
        static int poolIndex;
        static GameObject host;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        static void Reset() { clips.Clear(); lastPlayed.Clear(); ui = null; pool = null; host = null; MusicVolume = Mathf.Clamp01(PlayerPrefs.GetFloat(MusicPref, 1)); }

        public static void SetMusicVolume(float value, bool save)
        {
            MusicVolume = Mathf.Clamp01(value);
            if (save) { PlayerPrefs.SetFloat(MusicPref, MusicVolume); }
        }

        public static AudioClip Clip(string name)
        {
            if (clips.TryGetValue(name, out var clip))
            {
                if (clip) return clip;
                if (ReferenceEquals(clip, null)) return null; // known to be missing
            }
            clip = Resources.Load<AudioClip>(Folder + name);
            clips[name] = clip;
            return clip;
        }

        public static string Pick(string baseName, int count) => baseName + "_" + Random.Range(0, count);

        static void Ensure()
        {
            if (host && ui && pool != null) return;
            host = new GameObject("Hotel Audio") { hideFlags = HideFlags.HideAndDontSave };
            Object.DontDestroyOnLoad(host);
            ui = host.AddComponent<AudioSource>();
            ui.playOnAwake = false; ui.spatialBlend = 0; ui.ignoreListenerPause = true;
            pool = new AudioSource[14];
            for (int i = 0; i < pool.Length; i++)
            {
                var source = new GameObject("sfx " + i).AddComponent<AudioSource>();
                source.transform.SetParent(host.transform, false);
                source.playOnAwake = false; source.spatialBlend = 1; source.rolloffMode = AudioRolloffMode.Linear;
                source.minDistance = 2; source.maxDistance = 32; source.dopplerLevel = 0;
                pool[i] = source;
            }
        }

        static bool Throttled(string name, float gap)
        {
            float now = Time.unscaledTime;
            if (lastPlayed.TryGetValue(name, out var last) && now - last < gap) return true;
            lastPlayed[name] = now; return false;
        }

        /// <summary>Non-positional sound (UI, wallet, stings). Still plays while the game is paused.</summary>
        public static void Play(string name, float volume = 1, float pitch = 1, float minGap = .035f)
        {
            var clip = Clip(name);
            if (!clip || Throttled(name, minGap)) return;
            Ensure();
            ui.pitch = pitch;
            ui.PlayOneShot(clip, volume * SfxVolume);
        }

        /// <summary>Positional sound from the pooled sources.</summary>
        public static void PlayAt(string name, Vector3 position, float volume = 1, float pitch = 1, float minGap = .03f, float maxDistance = 32)
        {
            var clip = Clip(name);
            if (!clip || Throttled(name + (int)(position.x * .5f) + ":" + (int)(position.z * .5f), minGap)) return;
            Ensure();
            var source = pool[poolIndex]; poolIndex = (poolIndex + 1) % pool.Length;
            source.Stop(); source.transform.position = position; source.maxDistance = maxDistance;
            source.pitch = pitch; source.volume = Mathf.Clamp01(volume * SfxVolume); source.clip = clip; source.Play();
        }

        /// <summary>Positional sound attached to an existing AudioSource (keeps its mixer/3D settings).</summary>
        public static void PlayOn(AudioSource source, string name, float volume = 1, float pitch = 1)
        {
            var clip = Clip(name);
            if (!clip || !source) return;
            source.pitch = pitch; source.PlayOneShot(clip, volume * SfxVolume);
        }

        public static bool Has(string name) => Clip(name);

        /// <summary>Returns the shipped clip when present (destroying the procedural fallback), otherwise the fallback.</summary>
        public static AudioClip Prefer(string name, AudioClip fallback)
        {
            var clip = Clip(name);
            if (!clip) return fallback;
            if (fallback && fallback != clip) Object.Destroy(fallback);
            return clip;
        }

        /// <summary>Destroys a procedural clip but never a clip loaded from Resources.</summary>
        public static void Release(AudioClip clip)
        {
            if (clip && !clips.ContainsValue(clip)) Object.Destroy(clip);
        }
    }
}
